package com.gullesurgames.xpalarm;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(XpAlarmConfig.CONFIG_GROUP)
public interface XpAlarmConfig extends Config
{
	String CONFIG_GROUP = "xpalarm";
	String ALARMS_LIST_KEY = "alarmsListJson";

	@ConfigItem(
		keyName = ALARMS_LIST_KEY,
		name = "Alarms JSON",
		description = "Serialized JSON payload containing all active and inactive XP alarms",
		hidden = true
	)
	default String alarmsListJson()
	{
		return "[]";
	}

	@Range(min = 5, max = 60)
	@ConfigItem(
		keyName = "flashDurationFrames",
		name = "Flash Duration (Frames)",
		description = "Number of client render frames the screen flash overlay remains visible",
		position = 1
	)
	default int flashDurationFrames()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "enableCustomSounds",
		name = "Enable Custom Sounds",
		description = "Enables loading and playing external .wav files from the plugin sounds directory (.runelite/plugin-data/xp-alarms/sounds/)",
		position = 2
	)
	default boolean enableCustomSounds()
	{
		return true;
	}
}

package com.gullesurgames.xpalarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Full-screen visual overlay that flashes a customizable color when an alarm threshold is triggered.
 */
@Singleton
public class XpAlarmOverlay extends Overlay
{
	private final Client client;

	private volatile boolean flashActive = false;
	private volatile Color flashColor = new Color(255, 0, 0, 140);
	private volatile int remainingFrames = 0;

	@Inject
	public XpAlarmOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(OverlayPriority.HIGHEST);
	}

	/**
	 * Activates the screen flash overlay.
	 *
	 * @param color The RGBA color to render.
	 * @param frameDuration Duration in game render frames.
	 */
	public synchronized void triggerFlash(Color color, int frameDuration)
	{
		this.flashColor = color != null ? color : new Color(255, 0, 0, 140);
		this.remainingFrames = Math.max(1, frameDuration);
		this.flashActive = true;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!flashActive)
		{
			return null;
		}

		synchronized (this)
		{
			if (remainingFrames <= 0)
			{
				flashActive = false;
				return null;
			}

			int width = client.getCanvasWidth();
			int height = client.getCanvasHeight();

			graphics.setColor(flashColor);
			graphics.fillRect(0, 0, width, height);

			remainingFrames--;
			if (remainingFrames <= 0)
			{
				flashActive = false;
			}
		}

		return null;
	}

	public synchronized void reset()
	{
		flashActive = false;
		remainingFrames = 0;
	}
}

package com.gullesurgames.xpalarm;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import com.gullesurgames.xpalarm.audio.CustomSoundManager;
import com.gullesurgames.xpalarm.model.AlarmMode;
import com.gullesurgames.xpalarm.model.SoundType;
import com.gullesurgames.xpalarm.model.XpAlarmTarget;
import com.gullesurgames.xpalarm.ui.XpAlarmPanel;
import com.gullesurgames.xpalarm.util.AlarmSerialization;
import java.io.IOException;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;

@Slf4j
@Singleton
@PluginDescriptor(
	name = "XP Alarm",
	description = "Customizable XP and level thresholds with screen flashes, sounds, and notifications",
	tags = {"xp", "experience", "level", "alarm", "flash", "sound", "notify"},
	internalName = "xp-alarms",
	legacyDataDirectory = "xpalarm"
)
public class XpAlarmPlugin extends Plugin
{
	@Inject
	@Getter
	private Client client;

	@Inject
	@Getter
	private ClientThread clientThread;

	@Inject
	private XpAlarmConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private XpAlarmOverlay overlay;

	@Inject
	@Getter
	private CustomSoundManager customSoundManager;

	@Inject
	private Notifier notifier;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	@Getter
	private AlarmSerialization alarmSerialization;

	private XpAlarmPanel panel;
	private NavigationButton navButton;

	@Getter
	private final List<XpAlarmTarget> alarms = Collections.synchronizedList(new ArrayList<>());
	private final Set<UUID> firedAlarmsSessionCache = ConcurrentHashMap.newKeySet();

	@Provides
	XpAlarmConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(XpAlarmConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		log.info("Starting XP Alarm plugin...");

		// Load alarms from configuration
		loadAlarms();

		// Ensure audio directories are initialized
		try
		{
			Filepath soundsDir = getPluginDirectory().join("sounds");
			customSoundManager.initDirectory(soundsDir);
		}
		catch (IOException e)
		{
			log.error("Failed to initialize custom sound directory", e);
		}

		// Register overlay
		overlayManager.add(overlay);

		// Initialize Swing UI Panel
		panel = new XpAlarmPanel(this);
		panel.refreshList();

		BufferedImage icon = createNavIcon();
		navButton = NavigationButton.builder()
			.tooltip("XP Alarms")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("Stopping XP Alarm plugin...");

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		overlayManager.remove(overlay);
		overlay.reset();
		customSoundManager.shutDown();

		alarms.clear();
		firedAlarmsSessionCache.clear();
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		Skill skill = statChanged.getSkill();
		int currentXp = statChanged.getXp();
		int currentLevel = statChanged.getLevel();

		// Calculate XP remaining to the next level
		int nextLevel = Math.min(Experience.MAX_VIRT_LEVEL, currentLevel + 1);
		int targetLevelXp = Experience.getXpForLevel(nextLevel);
		int remainingXpToNextLevel = Math.max(0, targetLevelXp - currentXp);

		boolean configNeedsSave = false;

		synchronized (alarms)
		{
			for (XpAlarmTarget alarm : alarms)
			{
				if (!alarm.isActive() || alarm.isTriggered() || alarm.getSkill() != skill)
				{
					continue;
				}

				if (firedAlarmsSessionCache.contains(alarm.getId()))
				{
					continue;
				}

				boolean conditionMet = false;

				if (alarm.getMode() == AlarmMode.ABSOLUTE_XP)
				{
					if (currentXp >= alarm.getThresholdValue())
					{
						conditionMet = true;
					}
				}
				else if (alarm.getMode() == AlarmMode.REMAINING_XP_TO_LEVEL)
				{
					if (remainingXpToNextLevel <= alarm.getThresholdValue())
					{
						conditionMet = true;
					}
				}

				if (conditionMet)
				{
					fireAlarm(alarm, currentXp, remainingXpToNextLevel);
					alarm.setTriggered(true);
					firedAlarmsSessionCache.add(alarm.getId());
					configNeedsSave = true;
				}
			}
		}

		if (configNeedsSave)
		{
			saveAlarms();
			if (panel != null)
			{
				panel.refreshList();
			}
		}
	}

	private void fireAlarm(XpAlarmTarget alarm, int currentXp, int remainingXp)
	{
		log.info("XP Alarm triggered for skill {} (mode: {}, threshold: {})",
			alarm.getSkill(), alarm.getMode(), alarm.getThresholdValue());

		// 1. Screen Flash Alert
		if (alarm.isFlashEnabled())
		{
			overlay.triggerFlash(alarm.getFlashColor(), config.flashDurationFrames());
		}

		// 2. Audio Alert
		if (alarm.isSoundEnabled())
		{
			if (alarm.getSoundType() == SoundType.BUILTIN)
			{
				clientThread.invokeLater(() -> client.playSoundEffect(alarm.getSoundId()));
			}
			else if (alarm.getSoundType() == SoundType.CUSTOM && config.enableCustomSounds())
			{
				customSoundManager.playCustomSound(alarm.getCustomSoundFileName());
			}
		}

		// 3. Desktop / Tray Notification
		if (alarm.isSystemAlertEnabled())
		{
			String msg = String.format("XP Alarm: %s reached target threshold! Current XP: %,d",
				alarm.getSkill().getName(), currentXp);
			notifier.notify(msg);
		}

		// 4. Formatted In-Game Chat Message
		if (alarm.isChatMessageEnabled())
		{
			String desc = alarm.getMode() == AlarmMode.ABSOLUTE_XP
				? String.format("Total XP: %,d (Target: %,d)", currentXp, alarm.getThresholdValue())
				: String.format("XP to Next Level: %,d (Target: %,d)", remainingXp, alarm.getThresholdValue());

			String chatMsg = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append("[XP Alarm] ")
				.append(ChatColorType.NORMAL)
				.append(alarm.getSkill().getName() + " alarm reached! " + desc)
				.build();

			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(chatMsg)
				.build());
		}
	}

	public void loadAlarms()
	{
		String json = config.alarmsListJson();
		List<XpAlarmTarget> loaded = alarmSerialization.fromJson(json);
		alarms.clear();
		alarms.addAll(loaded);

		firedAlarmsSessionCache.clear();
		for (XpAlarmTarget alarm : loaded)
		{
			if (alarm.isTriggered())
			{
				firedAlarmsSessionCache.add(alarm.getId());
			}
		}
	}

	public void saveAlarms()
	{
		String json = alarmSerialization.toJson(alarms);
		configManager.setConfiguration(XpAlarmConfig.CONFIG_GROUP, XpAlarmConfig.ALARMS_LIST_KEY, json);
	}

	public String exportAlarmsToBase64()
	{
		return alarmSerialization.exportToBase64(alarms);
	}

	public List<XpAlarmTarget> importAlarmsFromBase64(String base64) throws IllegalArgumentException
	{
		return alarmSerialization.importFromBase64(base64);
	}

	public void addAlarm(XpAlarmTarget alarm)
	{
		alarms.add(alarm);
		saveAlarms();
		if (panel != null)
		{
			panel.refreshList();
		}
	}

	public void updateAlarm(XpAlarmTarget updated)
	{
		synchronized (alarms)
		{
			for (int i = 0; i < alarms.size(); i++)
			{
				if (alarms.get(i).getId().equals(updated.getId()))
				{
					alarms.set(i, updated);
					// Reset fired session cache if alarm was edited
					firedAlarmsSessionCache.remove(updated.getId());
					break;
				}
			}
		}
		saveAlarms();
		if (panel != null)
		{
			panel.refreshList();
		}
	}

	public void deleteAlarm(UUID id)
	{
		alarms.removeIf(a -> a.getId().equals(id));
		firedAlarmsSessionCache.remove(id);
		saveAlarms();
	}

	public void rearmAlarm(UUID id)
	{
		firedAlarmsSessionCache.remove(id);
		synchronized (alarms)
		{
			for (XpAlarmTarget target : alarms)
			{
				if (target.getId().equals(id))
				{
					target.setTriggered(false);
					target.setActive(true);
					break;
				}
			}
		}
		saveAlarms();
	}

	public void mergeAlarms(List<XpAlarmTarget> newAlarms)
	{
		synchronized (alarms)
		{
			for (XpAlarmTarget na : newAlarms)
			{
				// Generate new UUID to prevent collision
				na.setId(UUID.randomUUID());
				na.setTriggered(false);
				alarms.add(na);
			}
		}
		saveAlarms();
		if (panel != null)
		{
			panel.refreshList();
		}
	}

	public void replaceAlarms(List<XpAlarmTarget> newAlarms)
	{
		synchronized (alarms)
		{
			alarms.clear();
			firedAlarmsSessionCache.clear();
			alarms.addAll(newAlarms);
		}
		saveAlarms();
		if (panel != null)
		{
			panel.refreshList();
		}
	}

	/**
	 * Generates a clean 16x16 bell/alarm icon procedurally with "XP" drawn on top
	 * for the side panel navigation button.
	 */
	private BufferedImage createNavIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Gold/Orange alarm bell
		g.setColor(new Color(230, 160, 40));
		g.fillArc(2, 2, 12, 11, 0, 180);
		g.fillRect(3, 7, 10, 4);

		// Bell rim
		g.setColor(new Color(250, 190, 60));
		g.fillRoundRect(1, 10, 14, 3, 2, 2);

		// Clapper
		g.setColor(new Color(200, 130, 20));
		g.fillOval(6, 12, 4, 3);

		// Top loop
		g.setColor(new Color(250, 190, 60));
		g.drawOval(6, 1, 3, 2);

		// Draw crisp "XP" lettering on the bell body
		g.setColor(new Color(28, 18, 5));
		// 'X' at x=4..6, y=4..8
		g.fillRect(4, 4, 1, 2);
		g.fillRect(6, 4, 1, 2);
		g.fillRect(5, 6, 1, 1);
		g.fillRect(4, 7, 1, 2);
		g.fillRect(6, 7, 1, 2);

		// 'P' at x=9..11, y=4..8
		g.fillRect(9, 4, 1, 5);
		g.fillRect(10, 4, 2, 1);
		g.fillRect(11, 5, 1, 1);
		g.fillRect(10, 6, 2, 1);

		g.dispose();
		return img;
	}
}

package com.gullesurgames.xpalarm.audio;

import java.io.IOException;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

/**
 * Manages loading and asynchronous playback of custom .wav audio files located in the plugin's sounds directory.
 */
@Slf4j
@Singleton
public class CustomSoundManager
{
	private final ExecutorService soundExecutor = Executors.newSingleThreadExecutor();
	private final AudioPlayer audioPlayer;

	@Getter
	private Filepath soundsDirectory;

	public CustomSoundManager()
	{
		this(new AudioPlayer());
	}

	@Inject
	public CustomSoundManager(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	/**
	 * Ensures the custom sounds directory structure exists on disk.
	 */
	public void initDirectory(Filepath dir)
	{
		this.soundsDirectory = dir;
		if (soundsDirectory != null && !soundsDirectory.exists())
		{
			try
			{
				soundsDirectory.createDirectories();
				log.info("Created custom XP Alarm sound directory at: {}", soundsDirectory);
			}
			catch (IOException e)
			{
				log.error("Failed to create custom sound directory: {}", soundsDirectory, e);
			}
		}
	}

	/**
	 * Scans the custom sounds directory for available .wav files.
	 */
	public List<String> getAvailableSoundFiles()
	{
		if (soundsDirectory == null || !soundsDirectory.exists() || !soundsDirectory.isDirectory())
		{
			return Collections.emptyList();
		}

		try (Stream<Filepath> stream = soundsDirectory.walk(1))
		{
			return stream
				.filter(fp -> !fp.equals(soundsDirectory) && fp.isFile())
				.map(Filepath::getFileName)
				.filter(name -> name.toLowerCase().endsWith(".wav"))
				.sorted()
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.error("Failed to list custom sound files from {}", soundsDirectory, e);
			return Collections.emptyList();
		}
	}

	/**
	 * Asynchronously plays a .wav audio clip by filename.
	 */
	public void playCustomSound(String fileName)
	{
		if (fileName == null || fileName.trim().isEmpty() || soundsDirectory == null)
		{
			return;
		}

		soundExecutor.submit(() -> {
			try
			{
				Filepath soundFile = soundsDirectory.join(fileName);
				if (!soundFile.exists() || !soundFile.isFile())
				{
					log.warn("Custom sound file not found: {}", soundFile);
					return;
				}

				audioPlayer.play(soundFile, 0.0f);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Invalid sound filename: {}", fileName, e);
			}
			catch (Exception e)
			{
				log.error("Failed to play custom sound: " + fileName, e);
			}
		});
	}

	/**
	 * Shuts down the sound executor service upon plugin shutdown.
	 */
	public void shutDown()
	{
		soundExecutor.shutdownNow();
	}
}

package com.gullesurgames.xpalarm.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Mode of evaluation for checking XP alarm thresholds.
 */
@Getter
@RequiredArgsConstructor
public enum AlarmMode
{
	ABSOLUTE_XP("Absolute XP"),
	REMAINING_XP_TO_LEVEL("XP Remaining to Next Level");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gullesurgames.xpalarm.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Type of audio cue played when an alarm threshold is triggered.
 */
@Getter
@RequiredArgsConstructor
public enum SoundType
{
	BUILTIN("Built-in Sound Effect"),
	CUSTOM("Custom WAV File");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gullesurgames.xpalarm.model;

import java.awt.Color;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.Skill;

/**
 * Model representing an independent XP or Level Alarm target.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class XpAlarmTarget
{
	@Builder.Default
	private UUID id = UUID.randomUUID();

	@Builder.Default
	private Skill skill = Skill.ATTACK;

	@Builder.Default
	private AlarmMode mode = AlarmMode.REMAINING_XP_TO_LEVEL;

	@Builder.Default
	private int thresholdValue = 1000;

	@Builder.Default
	private boolean flashEnabled = true;

	@Builder.Default
	private Color flashColor = new Color(255, 0, 0, 140);

	@Builder.Default
	private boolean soundEnabled = true;

	@Builder.Default
	private SoundType soundType = SoundType.BUILTIN;

	@Builder.Default
	private int soundId = 2266; // Level-up jingle default sound effect ID

	@Builder.Default
	private String customSoundFileName = "alarm.wav";

	@Builder.Default
	private boolean systemAlertEnabled = true;

	@Builder.Default
	private boolean chatMessageEnabled = true;

	@Builder.Default
	private boolean active = true;

	@Builder.Default
	private boolean triggered = false;

	/**
	 * Creates a deep copy of the alarm configuration for editing.
	 */
	public XpAlarmTarget deepCopy()
	{
		return XpAlarmTarget.builder()
			.id(this.id)
			.skill(this.skill)
			.mode(this.mode)
			.thresholdValue(this.thresholdValue)
			.flashEnabled(this.flashEnabled)
			.flashColor(new Color(this.flashColor.getRGB(), true))
			.soundEnabled(this.soundEnabled)
			.soundType(this.soundType)
			.soundId(this.soundId)
			.customSoundFileName(this.customSoundFileName)
			.systemAlertEnabled(this.systemAlertEnabled)
			.chatMessageEnabled(this.chatMessageEnabled)
			.active(this.active)
			.triggered(this.triggered)
			.build();
	}
}

package com.gullesurgames.xpalarm.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.text.NumberFormat;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import com.gullesurgames.xpalarm.XpAlarmPlugin;
import com.gullesurgames.xpalarm.model.AlarmMode;
import com.gullesurgames.xpalarm.model.XpAlarmTarget;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Visual card representing a single configured XP Alarm inside the panel list.
 */
public class AlarmCardPanel extends JPanel
{
	private static final NumberFormat NUMBER_FORMAT = NumberFormat.getIntegerInstance(Locale.US);

	private final XpAlarmPlugin plugin;
	private final XpAlarmPanel parentPanel;
	private final XpAlarmTarget alarm;

	public AlarmCardPanel(XpAlarmPlugin plugin, XpAlarmPanel parentPanel, XpAlarmTarget alarm)
	{
		this.plugin = plugin;
		this.parentPanel = parentPanel;
		this.alarm = alarm;

		setLayout(new BorderLayout(5, 5));
		setBackground(alarm.isActive() ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR.darker());
		setBorder(new CompoundBorder(
			new LineBorder(alarm.isTriggered() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BORDER_COLOR, 1),
			new EmptyBorder(8, 8, 8, 8)
		));

		initCardUi();
	}

	private void initCardUi()
	{
		// Top Bar: Skill Name + Active Checkbox
		JPanel headerPanel = new JPanel(new BorderLayout());
		headerPanel.setOpaque(false);

		JLabel skillLabel = new JLabel(alarm.getSkill().getName().toUpperCase());
		skillLabel.setFont(FontManager.getRunescapeBoldFont());
		skillLabel.setForeground(alarm.isActive() ? Color.WHITE : Color.GRAY);

		JCheckBox activeToggle = new JCheckBox();
		activeToggle.setSelected(alarm.isActive());
		activeToggle.setToolTipText(alarm.isActive() ? "Alarm Active (Click to disable)" : "Alarm Inactive (Click to enable)");
		activeToggle.setOpaque(false);
		activeToggle.addActionListener(e -> {
			alarm.setActive(activeToggle.isSelected());
			plugin.saveAlarms();
			parentPanel.refreshList();
		});

		headerPanel.add(skillLabel, BorderLayout.WEST);
		headerPanel.add(activeToggle, BorderLayout.EAST);
		add(headerPanel, BorderLayout.NORTH);

		// Center: Mode, Threshold, Badges
		JPanel bodyPanel = new JPanel();
		bodyPanel.setLayout(new BoxLayout(bodyPanel, BoxLayout.Y_AXIS));
		bodyPanel.setOpaque(false);

		String modeDesc = alarm.getMode() == AlarmMode.ABSOLUTE_XP ? "Absolute XP: " : "Remaining XP: ";
		JLabel thresholdLabel = new JLabel(modeDesc + NUMBER_FORMAT.format(alarm.getThresholdValue()));
		thresholdLabel.setFont(FontManager.getRunescapeSmallFont());
		thresholdLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		thresholdLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		bodyPanel.add(thresholdLabel);

		// Alert indicators row
		JPanel alertsRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		alertsRow.setOpaque(false);
		alertsRow.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (alarm.isFlashEnabled())
		{
			alertsRow.add(createBadge("FLASH", alarm.getFlashColor()));
		}
		if (alarm.isSoundEnabled())
		{
			alertsRow.add(createBadge("AUDIO", ColorScheme.PROGRESS_COMPLETE_COLOR));
		}
		if (alarm.isSystemAlertEnabled())
		{
			alertsRow.add(createBadge("NOTIF", ColorScheme.BRAND_ORANGE));
		}
		if (alarm.isChatMessageEnabled())
		{
			alertsRow.add(createBadge("CHAT", Color.CYAN));
		}

		if (alarm.isTriggered())
		{
			JLabel triggeredBadge = createBadge("TRIGGERED", Color.RED);
			triggeredBadge.setToolTipText("Threshold met. Click Reset to re-arm.");
			alertsRow.add(triggeredBadge);
		}

		bodyPanel.add(Box.createVerticalStrut(4));
		bodyPanel.add(alertsRow);
		add(bodyPanel, BorderLayout.CENTER);

		// Bottom / Actions: Re-arm (if triggered), Edit, Delete
		JPanel actionsPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		actionsPanel.setOpaque(false);

		if (alarm.isTriggered())
		{
			JButton rearmButton = createSmallButton("Rearm", "Re-arm this alarm to trigger again");
			rearmButton.addActionListener(e -> {
				alarm.setTriggered(false);
				plugin.rearmAlarm(alarm.getId());
				parentPanel.refreshList();
			});
			actionsPanel.add(rearmButton);
		}

		JButton editButton = createSmallButton("Edit", "Edit alarm parameters");
		editButton.addActionListener(e -> parentPanel.showEditor(alarm));
		actionsPanel.add(editButton);

		JButton deleteButton = createSmallButton("Delete", "Delete this alarm");
		deleteButton.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		deleteButton.addActionListener(e -> {
			plugin.deleteAlarm(alarm.getId());
			parentPanel.refreshList();
		});
		actionsPanel.add(deleteButton);

		add(actionsPanel, BorderLayout.SOUTH);
	}

	private JLabel createBadge(String text, Color color)
	{
		JLabel badge = new JLabel(text);
		badge.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
		badge.setForeground(Color.WHITE);
		badge.setOpaque(true);
		badge.setBackground(color);
		badge.setBorder(new CompoundBorder(
			new LineBorder(color.darker(), 1),
			new EmptyBorder(1, 3, 1, 3)
		));
		return badge;
	}

	private JButton createSmallButton(String text, String tooltip)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setMargin(new java.awt.Insets(1, 3, 1, 3));
		button.setPreferredSize(new Dimension(button.getPreferredSize().width, 22));
		button.setCursor(new Cursor(Cursor.HAND_CURSOR));
		button.setToolTipText(tooltip);
		return button;
	}
}

