	private void exportToClipboard()
	{
		List<XpAlarmTarget> alarms = plugin.getAlarms();
		if (alarms.isEmpty())
		{
			JOptionPane.showMessageDialog(this, "No alarms configured to export.", "Export Alarms", JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		try
		{
			String b64 = plugin.exportAlarmsToBase64();
			Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
			clipboard.setContents(new StringSelection(b64), null);
			JOptionPane.showMessageDialog(this, "Exported " + alarms.size() + " alarm(s) to clipboard as Base64 string!", "Export Successful", JOptionPane.INFORMATION_MESSAGE);
		}
		catch (Exception e)
		{
			log.error("Failed to export alarms to clipboard", e);
			JOptionPane.showMessageDialog(this, "Failed to export alarms: " + e.getMessage(), "Export Error", JOptionPane.ERROR_MESSAGE);
		}
	}

	private void importFromClipboard()
	{
		String clipboardText = "";
		try
		{
			Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
			if (clipboard.isDataFlavorAvailable(DataFlavor.stringFlavor))
			{
				clipboardText = (String) clipboard.getData(DataFlavor.stringFlavor);
			}
		}
		catch (Exception ignored) {}

		JTextArea inputArea = new JTextArea(clipboardText, 5, 25);
		inputArea.setLineWrap(true);
		inputArea.setWrapStyleWord(true);
		JScrollPane scrollPane = new JScrollPane(inputArea);

		int option = JOptionPane.showConfirmDialog(
			this,
			scrollPane,
			"Paste Base64 Alarms String",
			JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE
		);

		if (option != JOptionPane.OK_OPTION)
		{
			return;
		}

		String payload = inputArea.getText().trim();
		if (payload.isEmpty())
		{
			return;
		}

		try
		{
			List<XpAlarmTarget> imported = plugin.importAlarmsFromBase64(payload);
			if (imported.isEmpty())
			{
				JOptionPane.showMessageDialog(this, "No valid alarms found in provided payload.", "Import Alarms", JOptionPane.WARNING_MESSAGE);
				return;
			}

			Object[] choices = {"Merge With Existing", "Overwrite All", "Cancel"};
			int mode = JOptionPane.showOptionDialog(
				this,
				"Imported " + imported.size() + " alarm(s). Choose import action:",
				"Import Options",
				JOptionPane.DEFAULT_OPTION,
				JOptionPane.QUESTION_MESSAGE,
				null,
				choices,
				choices[0]
			);

			if (mode == 0) // Merge
			{
				plugin.mergeAlarms(imported);
			}
			else if (mode == 1) // Overwrite
			{
				plugin.replaceAlarms(imported);
			}
		}
		catch (Exception ex)
		{
			JOptionPane.showMessageDialog(this, "Failed to import alarms: " + ex.getMessage(), "Import Error", JOptionPane.ERROR_MESSAGE);
		}
	}
}

package com.gullesurgames.xpalarm.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import com.gullesurgames.xpalarm.model.XpAlarmTarget;

/**
 * Utility for JSON and Base64 serialization and deserialization of XP Alarms.
 */
@Slf4j
@Singleton
public class AlarmSerialization
{
	private static final Type ALARM_LIST_TYPE = new TypeToken<List<XpAlarmTarget>>() {}.getType();

	private final Gson gson;

	@Inject
	public AlarmSerialization(Gson clientGson)
	{
		this.gson = clientGson.newBuilder()
			.registerTypeAdapter(Color.class, new ColorAdapter())
			.create();
	}

	public String toJson(List<XpAlarmTarget> alarms)
	{
		if (alarms == null || alarms.isEmpty())
		{
			return "[]";
		}
		return gson.toJson(alarms, ALARM_LIST_TYPE);
	}

	public List<XpAlarmTarget> fromJson(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<XpAlarmTarget> list = gson.fromJson(json, ALARM_LIST_TYPE);
			return list != null ? list : new ArrayList<>();
		}
		catch (Exception e)
		{
			log.error("Failed to parse XP alarm JSON payload", e);
			return new ArrayList<>();
		}
	}

	public String exportToBase64(List<XpAlarmTarget> alarms)
	{
		String json = toJson(alarms);
		return Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	public List<XpAlarmTarget> importFromBase64(String base64) throws IllegalArgumentException
	{
		if (base64 == null || base64.trim().isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			byte[] decoded = Base64.getDecoder().decode(base64.trim());
			String json = new String(decoded, StandardCharsets.UTF_8);
			return fromJson(json);
		}
		catch (Exception e)
		{
			log.error("Failed to decode Base64 alarms string", e);
			throw new IllegalArgumentException("Invalid Base64 alarm payload", e);
		}
	}
}

package com.gullesurgames.xpalarm.util;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.awt.Color;
import java.io.IOException;

/**
 * Custom Gson TypeAdapter for serializing and deserializing java.awt.Color with alpha transparency.
 */
public class ColorAdapter extends TypeAdapter<Color>
{
	@Override
	public void write(JsonWriter out, Color value) throws IOException
	{
		if (value == null)
		{
			out.nullValue();
			return;
		}
		// Write 32-bit ARGB hex string (#AARRGGBB)
		out.value(String.format("#%08X", value.getRGB()));
	}

	@Override
	public Color read(JsonReader in) throws IOException
	{
		if (in.peek() == JsonToken.NULL)
		{
			in.nextNull();
			return null;
		}

		String str = in.nextString();
		try
		{
			if (str.startsWith("#"))
			{
				long parsed = Long.parseUnsignedLong(str.substring(1), 16);
				return new Color((int) parsed, true);
			}
			else
			{
				long parsed = Long.parseLong(str);
				return new Color((int) parsed, true);
			}
		}
		catch (Exception ex)
		{
			return new Color(255, 0, 0, 140);
		}
	}
}

package com.gullesurgames.xpalarm;

import com.gullesurgames.xpalarm.model.AlarmMode;
import com.gullesurgames.xpalarm.model.SoundType;
import org.junit.Assert;
import org.junit.Test;

public class AlarmEnumsTest
{
	@Test
	public void testAlarmModeEnumValuesAndNames()
	{
		AlarmMode[] modes = AlarmMode.values();
		Assert.assertEquals(2, modes.length);

		// ValueOf lookup
		Assert.assertEquals(AlarmMode.ABSOLUTE_XP, AlarmMode.valueOf("ABSOLUTE_XP"));
		Assert.assertEquals(AlarmMode.REMAINING_XP_TO_LEVEL, AlarmMode.valueOf("REMAINING_XP_TO_LEVEL"));

		// Absolute XP
		Assert.assertEquals("Absolute XP", AlarmMode.ABSOLUTE_XP.getDisplayName());
		Assert.assertEquals("Absolute XP", AlarmMode.ABSOLUTE_XP.toString());

		// XP Remaining to Next Level
		Assert.assertEquals("XP Remaining to Next Level", AlarmMode.REMAINING_XP_TO_LEVEL.getDisplayName());
		Assert.assertEquals("XP Remaining to Next Level", AlarmMode.REMAINING_XP_TO_LEVEL.toString());

		// Invariant: toString() matches getDisplayName()
		for (AlarmMode mode : modes)
		{
			Assert.assertEquals(mode.getDisplayName(), mode.toString());
		}
	}

	@Test
	public void testSoundTypeEnumValuesAndNames()
	{
		SoundType[] types = SoundType.values();
		Assert.assertEquals(2, types.length);

		// ValueOf lookup
		Assert.assertEquals(SoundType.BUILTIN, SoundType.valueOf("BUILTIN"));
		Assert.assertEquals(SoundType.CUSTOM, SoundType.valueOf("CUSTOM"));

		// Builtin
		Assert.assertEquals("Built-in Sound Effect", SoundType.BUILTIN.getDisplayName());
		Assert.assertEquals("Built-in Sound Effect", SoundType.BUILTIN.toString());

		// Custom
		Assert.assertEquals("Custom WAV File", SoundType.CUSTOM.getDisplayName());
		Assert.assertEquals("Custom WAV File", SoundType.CUSTOM.toString());

		// Invariant: toString() matches getDisplayName()
		for (SoundType type : types)
		{
			Assert.assertEquals(type.getDisplayName(), type.toString());
		}
	}
}

