			.triggered(false)
			.build());

		// 5. Hitpoints 1 XP remaining final-hit alarm
		originalAlarms.add(XpAlarmTarget.builder()
			.id(UUID.randomUUID())
			.skill(Skill.HITPOINTS)
			.mode(AlarmMode.REMAINING_XP_TO_LEVEL)
			.thresholdValue(1)
			.flashEnabled(true)
			.flashColor(new Color(255, 50, 50, 255))
			.soundEnabled(true)
			.soundType(SoundType.BUILTIN)
			.soundId(3924)
			.customSoundFileName("alarm.wav")
			.systemAlertEnabled(false)
			.chatMessageEnabled(true)
			.active(true)
			.triggered(false)
			.build());

		// Export
		String exportedBase64 = alarmSerialization.exportToBase64(originalAlarms);
		Assert.assertNotNull(exportedBase64);
		Assert.assertFalse(exportedBase64.isEmpty());

		// Import
		List<XpAlarmTarget> importedAlarms = alarmSerialization.importFromBase64(exportedBase64);
		Assert.assertNotNull(importedAlarms);
		Assert.assertEquals(originalAlarms.size(), importedAlarms.size());

		// Verify every alarm and its properties
		for (int i = 0; i < originalAlarms.size(); i++)
		{
			XpAlarmTarget expected = originalAlarms.get(i);
			XpAlarmTarget actual = importedAlarms.get(i);

			Assert.assertEquals("ID mismatch at index " + i, expected.getId(), actual.getId());
			Assert.assertEquals("Skill mismatch at index " + i, expected.getSkill(), actual.getSkill());
			Assert.assertEquals("Mode mismatch at index " + i, expected.getMode(), actual.getMode());
			Assert.assertEquals("Threshold mismatch at index " + i, expected.getThresholdValue(), actual.getThresholdValue());
			Assert.assertEquals("FlashEnabled mismatch at index " + i, expected.isFlashEnabled(), actual.isFlashEnabled());
			Assert.assertEquals("FlashColor RGB mismatch at index " + i, expected.getFlashColor().getRGB(), actual.getFlashColor().getRGB());
			Assert.assertEquals("SoundEnabled mismatch at index " + i, expected.isSoundEnabled(), actual.isSoundEnabled());
			Assert.assertEquals("SoundType mismatch at index " + i, expected.getSoundType(), actual.getSoundType());
			Assert.assertEquals("SoundId mismatch at index " + i, expected.getSoundId(), actual.getSoundId());
			Assert.assertEquals("CustomSoundFileName mismatch at index " + i, expected.getCustomSoundFileName(), actual.getCustomSoundFileName());
			Assert.assertEquals("SystemAlertEnabled mismatch at index " + i, expected.isSystemAlertEnabled(), actual.isSystemAlertEnabled());
			Assert.assertEquals("ChatMessageEnabled mismatch at index " + i, expected.isChatMessageEnabled(), actual.isChatMessageEnabled());
			Assert.assertEquals("Active mismatch at index " + i, expected.isActive(), actual.isActive());
			Assert.assertEquals("Triggered mismatch at index " + i, expected.isTriggered(), actual.isTriggered());
		}
	}
}

package com.gullesurgames.xpalarm;

import com.google.gson.Gson;
import java.awt.Color;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import net.runelite.api.Skill;
import com.gullesurgames.xpalarm.model.AlarmMode;
import com.gullesurgames.xpalarm.model.SoundType;
import com.gullesurgames.xpalarm.model.XpAlarmTarget;
import com.gullesurgames.xpalarm.util.AlarmSerialization;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

public class AlarmSerializationTest
{
	private AlarmSerialization alarmSerialization;

	@Before
	public void setUp()
	{
		alarmSerialization = new AlarmSerialization(new Gson());
	}

	@Test
	public void testSerializationRoundTrip()
	{
		UUID id = UUID.randomUUID();
		XpAlarmTarget target = XpAlarmTarget.builder()
			.id(id)
			.skill(Skill.SLAYER)
			.mode(AlarmMode.REMAINING_XP_TO_LEVEL)
			.thresholdValue(5000)
			.flashEnabled(true)
			.flashColor(new Color(0, 255, 128, 150))
			.soundEnabled(true)
			.soundType(SoundType.CUSTOM)
			.soundId(2266)
			.customSoundFileName("slayer_ding.wav")
			.systemAlertEnabled(true)
			.chatMessageEnabled(true)
			.active(true)
			.triggered(false)
			.build();

		List<XpAlarmTarget> list = Collections.singletonList(target);

		String json = alarmSerialization.toJson(list);
		Assert.assertNotNull(json);

		List<XpAlarmTarget> deserialized = alarmSerialization.fromJson(json);
		Assert.assertEquals(1, deserialized.size());

		XpAlarmTarget restored = deserialized.get(0);
		Assert.assertEquals(target.getId(), restored.getId());
		Assert.assertEquals(target.getSkill(), restored.getSkill());
		Assert.assertEquals(target.getMode(), restored.getMode());
		Assert.assertEquals(target.getThresholdValue(), restored.getThresholdValue());
		Assert.assertEquals(target.getFlashColor().getRGB(), restored.getFlashColor().getRGB());
		Assert.assertEquals(target.getCustomSoundFileName(), restored.getCustomSoundFileName());
	}

	@Test
	public void testBase64ExportAndImport()
	{
		XpAlarmTarget target = XpAlarmTarget.builder()
			.id(UUID.randomUUID())
			.skill(Skill.WOODCUTTING)
			.mode(AlarmMode.ABSOLUTE_XP)
			.thresholdValue(13034431)
			.flashEnabled(false)
			.flashColor(Color.RED)
			.soundEnabled(true)
			.soundType(SoundType.BUILTIN)
			.soundId(2266)
			.customSoundFileName("test.wav")
			.systemAlertEnabled(false)
			.chatMessageEnabled(true)
			.active(true)
			.triggered(true)
			.build();

		String b64 = alarmSerialization.exportToBase64(Collections.singletonList(target));
		Assert.assertNotNull(b64);

		List<XpAlarmTarget> imported = alarmSerialization.importFromBase64(b64);
		Assert.assertEquals(1, imported.size());
		Assert.assertEquals(Skill.WOODCUTTING, imported.get(0).getSkill());
		Assert.assertEquals(13034431, imported.get(0).getThresholdValue());
	}
}

package com.gullesurgames.xpalarm;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import java.awt.Color;
import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import com.gullesurgames.xpalarm.util.ColorAdapter;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

public class ColorAdapterTest
{
	private ColorAdapter colorAdapter;
	private Gson gson;

	@Before
	public void setUp()
	{
		colorAdapter = new ColorAdapter();
		gson = new GsonBuilder()
			.registerTypeAdapter(Color.class, colorAdapter)
			.create();
	}

	@Test
	public void testSerializeColorWithAlpha()
	{
		// Test ARGB with alpha transparency (alpha=150, red=255, green=0, blue=128)
		Color transparentColor = new Color(255, 0, 128, 150);
		String json = gson.toJson(transparentColor);
		// 150 = 0x96, 255 = 0xFF, 0 = 0x00, 128 = 0x80 -> #96FF0080
		Assert.assertEquals("\"#96FF0080\"", json);

		// Test fully opaque color
		Color opaqueColor = new Color(0, 255, 64, 255);
		Assert.assertEquals("\"#FF00FF40\"", gson.toJson(opaqueColor));

		// Test fully transparent color
		Color fullyTransparent = new Color(0, 0, 0, 0);
		Assert.assertEquals("\"#00000000\"", gson.toJson(fullyTransparent));
	}

	@Test
	public void testSerializeNullColor()
	{
		String json = gson.toJson(null, Color.class);
		Assert.assertEquals("null", json);
	}

	@Test
	public void testDeserializeHexFormatStrings()
	{
		// Test standard uppercase hex with alpha
		Color c1 = gson.fromJson("\"#96FF0080\"", Color.class);
		Assert.assertNotNull(c1);
		Assert.assertEquals(150, c1.getAlpha());
		Assert.assertEquals(255, c1.getRed());
		Assert.assertEquals(0, c1.getGreen());
		Assert.assertEquals(128, c1.getBlue());

		// Test lowercase hex
		Color c2 = gson.fromJson("\"#ff00ff40\"", Color.class);
		Assert.assertNotNull(c2);
		Assert.assertEquals(255, c2.getAlpha());
		Assert.assertEquals(0, c2.getRed());
		Assert.assertEquals(255, c2.getGreen());
		Assert.assertEquals(64, c2.getBlue());

		// Test fully transparent
		Color c3 = gson.fromJson("\"#00000000\"", Color.class);
		Assert.assertNotNull(c3);
		Assert.assertEquals(0, c3.getAlpha());
		Assert.assertEquals(0, c3.getRed());
		Assert.assertEquals(0, c3.getGreen());
		Assert.assertEquals(0, c3.getBlue());
	}

	@Test
	public void testDeserializeLegacyNumericStrings()
	{
		// Test legacy negative signed integer string (e.g. Color.RED.getRGB() = -65536)
		int redRgb = Color.RED.getRGB();
		Color c1 = gson.fromJson("\"" + redRgb + "\"", Color.class);
		Assert.assertNotNull(c1);
		Assert.assertEquals(Color.RED.getRGB(), c1.getRGB());
		Assert.assertEquals(255, c1.getAlpha());
		Assert.assertEquals(255, c1.getRed());
		Assert.assertEquals(0, c1.getGreen());
		Assert.assertEquals(0, c1.getBlue());

		// Test legacy color with custom alpha
		Color customColor = new Color(100, 150, 200, 75);
		int customRgb = customColor.getRGB();
		Color c2 = gson.fromJson("\"" + customRgb + "\"", Color.class);
		Assert.assertNotNull(c2);
		Assert.assertEquals(customColor.getRGB(), c2.getRGB());
		Assert.assertEquals(75, c2.getAlpha());
		Assert.assertEquals(100, c2.getRed());
		Assert.assertEquals(150, c2.getGreen());
		Assert.assertEquals(200, c2.getBlue());
	}

	@Test
	public void testDeserializeFallbackOnNullOrInvalidValues()
	{
		// Null JSON token returns null
		Color nullColor = gson.fromJson("null", Color.class);
		Assert.assertNull(nullColor);

		// Fallback color is default new Color(255, 0, 0, 140)
		Color expectedFallback = new Color(255, 0, 0, 140);

		// Non-color string
		Color invalidStr = gson.fromJson("\"not-a-color\"", Color.class);
		Assert.assertEquals(expectedFallback, invalidStr);

		// Empty string
		Color emptyStr = gson.fromJson("\"\"", Color.class);
		Assert.assertEquals(expectedFallback, emptyStr);

		// Invalid hex string
		Color invalidHex = gson.fromJson("\"#GGHHIIJJ\"", Color.class);
		Assert.assertEquals(expectedFallback, invalidHex);

		// Malformed hash prefix
		Color malformedHash = gson.fromJson("\"###\"", Color.class);
		Assert.assertEquals(expectedFallback, malformedHash);
	}

	@Test
	public void testDirectTypeAdapterWriteAndRead() throws IOException
	{
		// Direct write null
		StringWriter sw = new StringWriter();
		JsonWriter writer = new JsonWriter(sw);
		colorAdapter.write(writer, null);
		Assert.assertEquals("null", sw.toString());

		// Direct write color
		sw = new StringWriter();
		writer = new JsonWriter(sw);
		colorAdapter.write(writer, new Color(12, 34, 56, 78));
		Assert.assertEquals("\"#4E0C2238\"", sw.toString());

		// Direct read null
		JsonReader reader = new JsonReader(new StringReader("null"));
		Assert.assertNull(colorAdapter.read(reader));

		// Direct read valid hex
		reader = new JsonReader(new StringReader("\"#4E0C2238\""));
		Color readColor = colorAdapter.read(reader);
		Assert.assertEquals(78, readColor.getAlpha());
		Assert.assertEquals(12, readColor.getRed());
		Assert.assertEquals(34, readColor.getGreen());
		Assert.assertEquals(56, readColor.getBlue());
	}
}

package com.gullesurgames.xpalarm;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.function.Predicate;
import com.gullesurgames.xpalarm.audio.CustomSoundManager;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

public class CustomSoundManagerTest
{
	private CustomSoundManager soundManager;
	private Path tempDirPath;
	private Filepath soundsDir;

	@Before
	public void setUp() throws IOException
	{
		tempDirPath = Files.createTempDirectory("xpalarm_test_sounds");
		soundsDir = Filepath.Unchecked.getRooted(tempDirPath);
		soundManager = new CustomSoundManager();
		soundManager.initDirectory(soundsDir);
	}

	@After
	public void tearDown() throws IOException
	{
		if (soundsDir != null && soundsDir.exists())
		{
			soundsDir.deleteRecursively();
		}

		if (soundManager != null)
		{
			soundManager.shutDown();
		}
	}

	@Test
	public void testFileExtensionFilteringWithActualFiles() throws IOException
	{
		Assert.assertNotNull(soundsDir);
		Assert.assertTrue("Sounds directory must exist", soundsDir.exists() && soundsDir.isDirectory());

		// Create files with diverse extensions and casings
		String prefix = "xpalarm_test_" + System.currentTimeMillis() + "_";

		Filepath lowerWav = soundsDir.join(prefix + "lower.wav");
		Filepath upperWav = soundsDir.join(prefix + "upper.WAV");
		Filepath mixedWav = soundsDir.join(prefix + "mixed.Wav");
		Filepath mp3File = soundsDir.join(prefix + "audio.mp3");
		Filepath txtFile = soundsDir.join(prefix + "readme.txt");
		Filepath bakFile = soundsDir.join(prefix + "sound.wav.bak");
		Filepath oggFile = soundsDir.join(prefix + "clip.ogg");

		List<Filepath> toCreate = List.of(lowerWav, upperWav, mixedWav, mp3File, txtFile, bakFile, oggFile);
		for (Filepath f : toCreate)
		{
			f.write(new byte[0]);
		}

		List<String> available = soundManager.getAvailableSoundFiles();
		Assert.assertNotNull(available);

		// Verified that .wav files (case-insensitive) are accepted
		Assert.assertTrue("Should contain lowercase .wav", available.contains(lowerWav.getFileName()));
		Assert.assertTrue("Should contain uppercase .WAV", available.contains(upperWav.getFileName()));
		Assert.assertTrue("Should contain mixed case .Wav", available.contains(mixedWav.getFileName()));

		// Verified that non-wav files are filtered out
		Assert.assertFalse("Should not contain .mp3", available.contains(mp3File.getFileName()));
		Assert.assertFalse("Should not contain .txt", available.contains(txtFile.getFileName()));
		Assert.assertFalse("Should not contain .wav.bak", available.contains(bakFile.getFileName()));
		Assert.assertFalse("Should not contain .ogg", available.contains(oggFile.getFileName()));
	}

	@Test
	public void testWavFilterPredicateLogic()
	{
		// Test the exact .wav extension matching predicate used by CustomSoundManager
		Predicate<String> filter = name -> name.toLowerCase().endsWith(".wav");

		// Should match .wav in any casing
		Assert.assertTrue(filter.test("alert.wav"));
		Assert.assertTrue(filter.test("ALERT.WAV"));
		Assert.assertTrue(filter.test("Alert.Wav"));
		Assert.assertTrue(filter.test("sound_effect.wAv"));
		Assert.assertTrue(filter.test(".wav"));

		// Should reject non-wav files
		Assert.assertFalse(filter.test("alert.mp3"));
		Assert.assertFalse(filter.test("alert.txt"));
		Assert.assertFalse(filter.test("alert.wav.bak"));
		Assert.assertFalse(filter.test("alert.wav.tmp"));
		Assert.assertFalse(filter.test("wav"));
		Assert.assertFalse(filter.test("alert.ogg"));
		Assert.assertFalse(filter.test("alert.flac"));
		Assert.assertFalse(filter.test("alert.aiff"));
	}

	@Test
	public void testPlayCustomSoundEdgeCasesDoNotThrow()
	{
		// Null, empty, whitespace, non-existent, and invalid character files should be handled gracefully without throwing
		soundManager.playCustomSound(null);
		soundManager.playCustomSound("");
		soundManager.playCustomSound("   ");
		soundManager.playCustomSound("non_existent_sound_12345.wav");
		soundManager.playCustomSound("invalid<>name.wav");
	}

	@Test
	public void testUninitializedManagerHandlesCallsSafely()
	{
		CustomSoundManager uninit = new CustomSoundManager();
		Assert.assertNotNull(uninit.getAvailableSoundFiles());
		Assert.assertTrue(uninit.getAvailableSoundFiles().isEmpty());
		Assert.assertNull(uninit.getSoundsDirectory());
		uninit.playCustomSound("test.wav");
		uninit.shutDown();
	}
}

