			panels[1] = new XpAlarmPanel(plugin);
			panels[1].refreshList();
			panels[1].showNewAlarmEditor();
		});

		// Allow pending EDT events from refreshList() to complete
		SwingUtilities.invokeAndWait(() -> {});
		Thread.sleep(150);
		SwingUtilities.invokeAndWait(() -> {
			try
			{
				if (artifactDir.exists())
